// Build dataset-derived letter prototypes from real MediaPipe landmarks.
//
// Input: JSON file shaped { "A": [[[x,y,z]×21]×N], ... } (normalized canonical
// frame, chirality-canonical right-hand geometry) OR a JSONL file with rows
// { letter, lm: [[x,y,z]×21] }. Generated by extracting landmarks from the
// Marxulia/asl_sign_languages_alphabets_v03 dataset (HF) with MediaPipe
// hand_landmarker float16/1 — see README "Dataset grounding".
//
// Config (selected by held-out experiment over the full sample, see README):
// 24 static letters (J/Z excluded — movement letters, recognized by motion.js),
// k-means k=6 centroids per letter, per-dim whitening by mean within-class std.
// Held-out accuracy 85.2% (vs 40.6% for the old hand-authored prototypes).
//
// Usage: node scripts/build-prototypes.mjs <landmarks.json|samples.jsonl> [out]
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { extractFeatures, featureVector } from '../js/classifier.js';
import { canonicalLandmarks, STATIC_LETTERS } from '../js/geometry.js';

const repo = join(dirname(fileURLToPath(import.meta.url)), '..');
const K = 6;

function loadSamples(path) {
  if (path.endsWith('.jsonl')) {
    return rowsToSamples(readFileSync(path, 'utf8').trim().split('\n').map((l) => JSON.parse(l)));
  }
  const fx = JSON.parse(readFileSync(path, 'utf8'));
  return rowsToSamples(
    Object.entries(fx).flatMap(([letter, arrs]) => arrs.map((lm) => ({ letter, lm })))
  );
}
function rowsToSamples(rows) {
  return rows.map((r) => ({
    letter: r.letter,
    lm: r.lm.map((p) => (Array.isArray(p) ? { x: p[0], y: p[1], z: p[2] } : p)),
  }));
}

function sqdist(a, b) {
  let s = 0;
  for (let i = 0; i < a.length; i++) {
    const d = a[i] - b[i];
    s += d * d;
  }
  return s;
}

function nearest(vec, protos) {
  let best = null;
  for (const p of protos) {
    const d = Math.sqrt(sqdist(vec, p.vec) / vec.length);
    if (!best || d < best.distance) best = { letter: p.letter, distance: d };
  }
  return best;
}

function whiteningScale(byClass) {
  const dims = featureDim;
  const scale = new Array(dims).fill(0);
  let classes = 0;
  for (const vecs of Object.values(byClass)) {
    classes++;
    for (let d = 0; d < dims; d++) {
      const m = vecs.reduce((s, v) => s + v[d], 0) / vecs.length;
      scale[d] += Math.sqrt(vecs.reduce((s, v) => s + (v[d] - m) ** 2, 0) / vecs.length);
    }
  }
  return scale.map((s) => Math.max(1e-6, s / classes));
}

function kmeans(vecs, k, iters = 40) {
  const cents = [];
  for (let i = 0; i < k; i++) cents.push(vecs[Math.floor((i * vecs.length) / k)].slice());
  const assign = new Array(vecs.length).fill(0);
  for (let it = 0; it < iters; it++) {
    for (let i = 0; i < vecs.length; i++) {
      let bd = Infinity, bi = 0;
      for (let c = 0; c < cents.length; c++) {
        const d = sqdist(vecs[i], cents[c]);
        if (d < bd) { bd = d; bi = c; }
      }
      assign[i] = bi;
    }
    for (let c = 0; c < cents.length; c++) {
      const mem = vecs.filter((_, i) => assign[i] === c);
      if (!mem.length) continue;
      for (let d = 0; d < cents[c].length; d++) {
        cents[c][d] = mem.reduce((s, v) => s + v[d], 0) / mem.length;
      }
    }
  }
  return cents;
}

// ---- main ----
const inPath = process.argv[2];
const outPath = process.argv[3] || join(repo, 'js', 'prototypes.js');
const all = loadSamples(inPath);
const samples = all
  .filter((s) => !'JZ'.includes(s.letter))
  .map((s) => ({ ...s, f: extractFeatures(s.lm) }))
  .filter((s) => s.f);
const featureDim = featureVector(samples[0].f).length;
console.log(`samples: ${all.length} in, ${samples.length} usable (24 static letters)`);

const byClass = {};
for (const s of samples) (byClass[s.letter] ||= []).push(featureVector(s.f));
const SCALE = whiteningScale(byClass);
const whitened = Object.fromEntries(
  Object.entries(byClass).map(([L, vecs]) => [L, vecs.map((v) => v.map((x, d) => x / SCALE[d]))])
);

const protos = [];
for (const L of STATIC_LETTERS) {
  const vecs = whitened[L];
  if (!vecs || !vecs.length) throw new Error(`no samples for letter ${L}`);
  for (const vec of kmeans(vecs, Math.min(K, vecs.length))) protos.push({ letter: L, vec });
}

// Evaluate on the real samples (train-through) and on the committed fixtures
// (subset of the same extraction) for the report.
function evaluate(set, label) {
  let ok = 0;
  const conf = {};
  for (const s of set) {
    const v = featureVector(s.f).map((x, d) => x / SCALE[d]);
    const got = nearest(v, protos).letter;
    if (got === s.letter) ok++;
    else (conf[s.letter] ||= []).push(got);
  }
  console.log(`${label}: ${ok}/${set.length} = ${((ok / set.length) * 100).toFixed(1)}%`);
  for (const [L, gots] of Object.entries(conf).sort((a, b) => b[1].length - a[1].length).slice(0, 6)) {
    const tally = gots.reduce((m, g) => ((m[g] = (m[g] || 0) + 1), m), {});
    console.log(`  ${L} misread as ${JSON.stringify(tally)}`);
  }
}
evaluate(samples, 'train-through (all samples)');
const canonSet = STATIC_LETTERS.map((L) => ({ letter: L, f: extractFeatures(canonicalLandmarks(L)) }));
let canonOk = 0;
for (const s of canonSet) if (nearest(featureVector(s.f).map((x, d) => x / SCALE[d]), protos).letter === s.letter) canonOk++;
console.log(`canonical fixtures: ${canonOk}/${canonSet.length}`);

const banner = `// AUTO-GENERATED by scripts/build-prototypes.mjs — do not edit by hand.
//
// Dataset-grounded letter prototypes: k-means (${K}/letter) centroids over
// ${samples.length} real hand-landmark samples extracted with MediaPipe
// hand_landmarker float16/1 from the Hugging Face dataset
// Marxulia/asl_sign_languages_alphabets_v03 (A-Z; J/Z excluded — they are
// movement letters handled by js/motion.js). Vectors are whitened by SCALE
// (mean within-class std per feature dim) — classify() whitens the query
// with the same SCALE. Fully deterministic; regenerate anytime.
export default ${JSON.stringify(protos)};
export const SCALE = ${JSON.stringify(SCALE.map((x) => parseFloat(x.toFixed(6))))};
`;
writeFileSync(outPath, banner);
console.log(`wrote ${outPath} (${protos.length} prototypes, ${featureDim} dims)`);
